window.HOEREN_TESTS[11] = {"id":"tiere-und-haustiere","name":"Tiere und Haustiere","teile":[{"type":"mc","title":"Teil 1: Fünf kurze Texte","instruction":"Sie hören fünf kurze Texte. Sie hören jeden Text zweimal. Wählen Sie a, b oder c.","items":[{"transcript":"Liebe Tierfreunde, das Tierheim sucht ein neues Zuhause für unseren Hund Bruno. Er ist 4 Jahre alt, sehr lieb und gut mit Kindern. Bruno braucht aber viel Bewegung — ein kleiner Garten oder lange Spaziergänge sind ein Muss. Wer Interesse hat, kommt bitte am Samstag oder Sonntag von 10 bis 16 Uhr vorbei.","gender":"f","q":"Was braucht der Hund Bruno?","opts":["Viel Bewegung.","Ruhe und Stille.","Eine kleine Wohnung ohne Garten."],"correct":0},{"transcript":"Hallo Maria, hier ist die Tierarzt-Praxis Weber. Ihr Hund hatte gestern die Impfung. Wir wollten nur informieren, dass eine kleine Reaktion in den ersten zwei Tagen normal ist — etwas müde, kein Appetit. Wenn er fast 3 Tage nicht frisst, rufen Sie an. Sonst alles okay. Schöne Erholung für ihn!","gender":"m","q":"Was ist nach der Impfung normal?","opts":["Der Hund ist müde und hat wenig Appetit.","Der Hund frisst zwei Wochen lang nicht.","Der Hund hat viel Energie."],"correct":0},{"transcript":"Hi Tom, hier ist Lisa. Mein Kater ist letzte Nacht weggelaufen. Er war nirgendwo zu finden. Hast du ihn vielleicht gesehen? Du wohnst ja in der Nähe. Schwarz mit weißen Pfoten, etwa 5 Jahre alt. Bitte sag mir Bescheid, wenn du ihn siehst — er hat keinen Chip, ich mache mir große Sorgen.","gender":"f","q":"Was ist passiert?","opts":["Der Kater ist krank.","Der Kater ist weggelaufen.","Der Kater hat einen Chip bekommen."],"correct":1},{"transcript":"Achtung im Stadtpark: Hunde müssen ab heute überall an der Leine geführt werden. Nur im hinteren Bereich, am See, ist Freilauf erlaubt. Wer seinen Hund frei laufen lässt im falschen Bereich, zahlt 50 Euro Strafe. Wir bitten alle Hundebesitzer, das zu respektieren — wegen mehrerer Beschwerden anderer Besucher.","gender":"m","q":"Wo dürfen Hunde frei laufen?","opts":["Nirgendwo im Park.","Überall im Park.","Im hinteren Bereich am See."],"correct":2},{"transcript":"Hallo, ich rufe wegen meines Kanarienvogels an. Er singt seit drei Tagen nicht mehr und frisst sehr wenig. Sonst sieht er aber gesund aus, keine besonderen Zeichen. Können Sie heute oder morgen einen Termin geben? Sonst muss ich warten, bis Sie wieder offen sind. Mein Telefon haben Sie schon.","gender":"m","q":"Was ist das Problem mit dem Vogel?","opts":["Er ist gestorben.","Er singt nicht mehr und frisst wenig.","Er ist sehr nervös und unruhig."],"correct":1}]},{"type":"match","title":"Teil 2: Ein Gespräch","instruction":"Sie hören ein Gespräch. Sie hören den Text einmal. Wer kümmert sich um was? Wählen Sie für jede Person einen Buchstaben (a–i).","lines":[{"speaker":"Lisa","gender":"f","text":"Hallo Mutter! Am Wochenende fahren wir weg. Wer versorgt dann die Tiere zu Hause?"},{"speaker":"Mutter","gender":"f","text":"Ich habe schon mit allen telefoniert. Jeder bekommt eine eigene klare Aufgabe."},{"speaker":"Lisa","gender":"f","text":"Ich gehe mit dem Hund spazieren. Morgens und abends bekommt er eine Runde."},{"speaker":"Mutter","gender":"f","text":"Der Hund braucht Bewegung. Brauchen wir auch den Tierarzt?"},{"speaker":"Lisa","gender":"f","text":"Nein. Zum Tierarzt gehen wir diesmal nicht. Alle Tiere sind gesund."},{"speaker":"Mutter","gender":"f","text":"Annas Mutter wohnt nebenan und hat einen Schlüssel."},{"speaker":"Lisa","gender":"f","text":"Annas Mutter füttert die Katze. Sie kennt den Napf im oberen Schrank."},{"speaker":"Mutter","gender":"f","text":"Die Katze mag sie sehr. Tim kommt am Samstag schon früh vorbei."},{"speaker":"Lisa","gender":"f","text":"Tim pflegt den Kanarienvogel. Er wechselt das Wasser im kleinen Käfig jeden Morgen."},{"speaker":"Mutter","gender":"f","text":"Der Vogel singt bei frischem Wasser. Wer schaut nach den Fischen?"},{"speaker":"Lisa","gender":"f","text":"Annas Vater kümmert sich um die Fische. Er gibt ihnen nur eine kleine Portion."},{"speaker":"Mutter","gender":"f","text":"Wir geben nicht zu viel ins Becken. Waschen wir die Wäsche vor der Abreise?"},{"speaker":"Lisa","gender":"f","text":"Die Wäsche waschen wir nicht. Sie bleibt einfach bis Montag im Korb liegen."},{"speaker":"Mutter","gender":"f","text":"Wohnung und Post kann eine Person schaffen. Wer schaut nach der Post?"},{"speaker":"Lisa","gender":"f","text":"Lukas kontrolliert die Wohnung und holt die Post aus dem Kasten."},{"speaker":"Mutter","gender":"f","text":"Einverstanden. Ich lege den Zettel neben das Telefon. Wir fahren am Freitag los."}],"options":[{"letter":"a","text":"wäscht die Wäsche"},{"letter":"b","text":"geht zum Tierarzt"},{"letter":"c","text":"füttert die Katze"},{"letter":"d","text":"putzt die Wohnung"},{"letter":"e","text":"geht mit dem Hund spazieren"},{"letter":"f","text":"kontrolliert die Wohnung und holt die Post"},{"letter":"g","text":"kauft Tierfutter ein"},{"letter":"h","text":"kümmert sich um die Fische"},{"letter":"i","text":"pflegt den Kanarienvogel"}],"items":[{"person":"Lisa","correct":"e"},{"person":"Annas Mutter","correct":"c"},{"person":"Tim","correct":"i"},{"person":"Annas Vater","correct":"h"},{"person":"Lukas","correct":"f"}]},{"type":"mc","title":"Teil 3: Fünf kurze Gespräche","instruction":"Sie hören fünf kurze Gespräche. Sie hören jedes Gespräch einmal. Wählen Sie a, b oder c.","items":[{"lines":[{"speaker":"Verkäufer","gender":"m","text":"Welches Hundefutter möchten Sie?"},{"speaker":"Kundin","gender":"f","text":"Mein Hund ist schon alt — 12 Jahre. Kein Babywelpen-Futter mehr nötig."},{"speaker":"Verkäufer","gender":"m","text":"Für Senior-Hunde haben wir dieses spezielle Futter mit weniger Fett. Oder das normale Futter, aber kleinere Portion."},{"speaker":"Kundin","gender":"f","text":"Senior-Futter klingt besser, das nehme ich. Danke!"},{"speaker":"Verkäufer","gender":"m","text":"Gute Wahl! Soll ich es zum Auto tragen? Es ist schwer."}],"q":"Welches Futter nimmt die Kundin?","opts":["Normales Futter, kleine Portion.","Spezielles Senior-Futter.","Babywelpen-Futter."],"correct":1},{"lines":[{"speaker":"Tierarzt","gender":"m","text":"Wie geht es Ihrer Katze heute?"},{"speaker":"Besitzerin","gender":"f","text":"Sie ist noch müde, aber besser als gestern."},{"speaker":"Tierarzt","gender":"m","text":"Hat sie etwas gefressen?"},{"speaker":"Besitzerin","gender":"f","text":"Heute Morgen ein bisschen Nassfutter. Trockenfutter mag sie nicht, beides schon gar nicht."},{"speaker":"Tierarzt","gender":"m","text":"Sehr gut, dass sie wieder frisst. Geben Sie ihr weiter Nassfutter, das ist leichter zu verdauen. In einer Woche kommen Sie wieder."}],"q":"Was soll die Katze essen?","opts":["Nassfutter.","Trockenfutter.","Beides gleichzeitig."],"correct":0},{"lines":[{"speaker":"Anrufer","gender":"m","text":"Hallo, ich möchte Ihnen meinen Vogel zur Pension geben für eine Woche."},{"speaker":"Mitarbeiterin","gender":"f","text":"Welche Art Vogel und für welche Woche?"},{"speaker":"Anrufer","gender":"m","text":"Ein Wellensittich. Vom 10. bis 17. Juni."},{"speaker":"Mitarbeiterin","gender":"f","text":"Das geht. 15 Euro pro Tag, also 105 Euro für die Woche."},{"speaker":"Anrufer","gender":"m","text":"Okay, ich bringe ihn am 10. vorbei. Danke, tschüss!"},{"speaker":"Mitarbeiterin","gender":"f","text":"Bis zum 10. Juni! Bringen Sie Futter mit, bitte!"}],"q":"Wie viel kostet die Pension insgesamt?","opts":["15 Euro.","105 Euro.","150 Euro."],"correct":1},{"lines":[{"speaker":"Nachbar","gender":"m","text":"Ihr Hund bellt jeden Tag stundenlang, wenn Sie nicht zu Hause sind."},{"speaker":"Hundebesitzerin","gender":"f","text":"Oh, das tut mir leid. Ich wusste das nicht. Ich ignoriere das nicht, versprochen."},{"speaker":"Nachbar","gender":"m","text":"Können Sie eine Lösung finden? Vielleicht eine Hundebetreuung tagsüber?"},{"speaker":"Hundebesitzerin","gender":"f","text":"Gute Idee, ich melde ihn ab Montag bei der Hundeschule an. Weggeben will ich ihn nicht. Danke!"},{"speaker":"Nachbar","gender":"m","text":"Super, danke! Dann ist es bald ruhig, hoffentlich."}],"q":"Was macht die Hundebesitzerin?","opts":["Sie ignoriert das Problem.","Sie gibt den Hund weg.","Sie meldet den Hund zur Hundeschule an."],"correct":2},{"lines":[{"speaker":"Tochter","gender":"f","text":"Papa, kann ich einen Hund haben?"},{"speaker":"Vater","gender":"m","text":"Hund ist viel Verantwortung. Hast du dir das überlegt?"},{"speaker":"Tochter","gender":"f","text":"Ja, ich gehe jeden Tag mit ihm spazieren, das verspreche ich."},{"speaker":"Vater","gender":"m","text":"Lass uns erst eine Katze ausprobieren. Wenn das gut geht, denken wir über einen Hund nach."},{"speaker":"Tochter","gender":"f","text":"Okay, Katze ist auch gut!"}],"q":"Welches Tier bekommt die Tochter?","opts":["Erstmal eine Katze.","Einen Hund sofort.","Gar kein Tier."],"correct":0}]},{"type":"jn","title":"Teil 4: Interview","instruction":"Sie hören ein Interview mit Herrn Vogel, einem Tierarzt. Sie hören das Interview zweimal. Ja oder Nein?","transcript":[{"speaker":"Reporter","gender":"m","text":"Herr Vogel, Sie sind Tierarzt seit 25 Jahren. Wie sind Sie zu diesem Beruf gekommen?"},{"speaker":"Vogel","gender":"m","text":"Mit 5 Jahren habe ich entschieden: Tierarzt werde ich. Meine Eltern hatten einen kleinen Bauernhof mit Kühen und Hühnern. Ich habe sehr früh angefangen, mich um die Tiere zu kümmern. Das war meine Welt."},{"speaker":"Reporter","gender":"m","text":"Welche Tiere behandeln Sie meistens?"},{"speaker":"Vogel","gender":"m","text":"Hunde und Katzen, das ist klar — 90 Prozent meiner Patienten. Manchmal Kaninchen oder Vögel. Aber auch noch große Tiere wie Pferde, weil ich in einer ländlichen Gegend arbeite. Schlangen behandle ich nicht — das ist nicht mein Spezialgebiet."},{"speaker":"Reporter","gender":"m","text":"Was ist das schwerste an Ihrem Beruf?"},{"speaker":"Vogel","gender":"m","text":"Wenn man ein Tier einschläfern muss. Das ist nie leicht. Manche Tierbesitzer weinen sehr stark, dann muss ich auch ruhig bleiben für sie. Das verlangt viel Kraft, auch nach 25 Jahren."},{"speaker":"Reporter","gender":"m","text":"Was macht Ihnen am meisten Spaß?"},{"speaker":"Vogel","gender":"m","text":"Wenn ich ein krankes Tier wieder gesund mache. Das Glück der Familie, die ihr Haustier zurück hat, ist unbezahlbar. Auch Geburten — wenn ich bei einer schwierigen Geburt helfe und das Baby-Tier lebt."},{"speaker":"Reporter","gender":"m","text":"Haben Sie selbst Haustiere?"},{"speaker":"Vogel","gender":"m","text":"Drei Katzen und einen Hund. Und mein Sohn hat einen Hamster. Wir leben quasi mit der ganzen Praxis zusammen!"}],"items":[{"q":"Herr Vogel wuchs auf einem Bauernhof auf.","correct":"ja"},{"q":"Er behandelt auch Schlangen.","correct":"nein"},{"q":"Tiere einschläfern wird mit der Zeit leichter.","correct":"nein"},{"q":"Bei einer Tier-Geburt mitzuhelfen macht ihm Freude.","correct":"ja"},{"q":"Er hat selbst nur einen Hund zu Hause.","correct":"nein"}]}]};
